/// A 4 px base, same as 24/7 IT. Use the steps.
abstract final class VpSpace {
  /// Icon to label inside a pill.
  static const double s1 = 4.0;
  /// Gap between inline items, compact table cell padding.
  static const double s2 = 8.0;
  /// Button vertical padding, nav item padding.
  static const double s3 = 12.0;
  /// Card padding on mobile, table cell padding, grid gutter.
  static const double s4 = 16.0;
  /// Card padding on desktop, gap between cards.
  static const double s5 = 24.0;
  /// Page padding, gap between sections.
  static const double s6 = 32.0;
  /// Login panel padding.
  static const double s7 = 48.0;
  /// Marketing section padding.
  static const double s8 = 64.0;
}

/// Rounded, never pill-shaped containers. The logo tile uses 22 percent of its width.
abstract final class VpRadius {
  /// Inputs, checkboxes, badges, table corners.
  static const double sm = 4.0;
  /// Buttons, banners, nav items, icon tiles.
  static const double md = 8.0;
  /// Cards, dialogs, image frames.
  static const double lg = 16.0;
  /// Status pills, toggles and waveform bars only.
  static const double pill = 999.0;
}

